{
  "PROP-1ada093f-inv-023": {
    "property_id": "PROP-1ada093f-inv-023",
    "text": "Transaction gas must not exceed TX_MAX_GAS_LIMIT (16,777,216) per EIP-7825.",
    "type": "invariant",
    "assertion": "forall validate_tx(tx): tx.gas <= 16777216",
    "severity": "HIGH",
    "covers": "SG-003",
    "reachability": {
      "classification": "external-reachable",
      "entry_points": [
        "P2P",
        "Transaction"
      ],
      "attacker_controlled": true,
      "bug_bounty_scope": "in-scope"
    },
    "exploitability": "external-attack",
    "code_scope": {
      "locations": [],
      "resolution_status": "not_found",
      "resolution_error": "Searched for: TX_MAX_GAS_LIMIT, GAS_CAP, 16777216, 0x1000000 across entire codebase. No per-transaction gas cap validation found. Only block-level gas accounting exists (eth/block.rs:111-119), which checks tx.gas_limit <= block.gas_limit - gas_used, but this is NOT the same as EIP-7825's absolute per-tx cap.",
      "resolution_method": null
    }
  }
}

