     1→use crate::EvmEnv;
     2→use alloy_consensus::BlockHeader;
     3→use alloy_eips::{eip7825::MAX_TX_GAS_LIMIT_OSAKA, eip7840::BlobParams};
     4→use alloy_hardforks::EthereumHardforks;
     5→use alloy_primitives::{Address, BlockNumber, BlockTimestamp, ChainId, B256, U256};
     6→use revm::{
     7→    context::{BlockEnv, CfgEnv},
     8→    context_interface::block::BlobExcessGasAndPrice,
     9→    primitives::hardfork::SpecId,
    10→};
    11→
    12→impl EvmEnv<SpecId> {
    13→    /// Create a new `EvmEnv` with [`SpecId`] from a block `header`, `chain_id`, `chain_spec` and
    14→    /// optional `blob_params`.
    15→    ///
    16→    /// # Arguments
    17→    ///
    18→    /// * `header` - The block to make the env out of.
    19→    /// * `chain_spec` - The chain hardfork description, must implement [`EthereumHardforks`].
    20→    /// * `chain_id` - The chain identifier.
    21→    /// * `blob_params` - Optional parameters that sets limits on gas and count for blobs.
    22→    pub fn for_eth_block(
    23→        header: impl BlockHeader,
    24→        chain_spec: impl EthereumHardforks,
    25→        chain_id: ChainId,
    26→        blob_params: Option<BlobParams>,
    27→    ) -> Self {
    28→        Self::for_eth(EvmEnvInput::from_block_header(header), chain_spec, chain_id, blob_params)
    29→    }
    30→
    31→    /// Create a new `EvmEnv` with [`SpecId`] from a parent block `header`, `chain_id`, `chain_spec`
    32→    /// and optional `blob_params`.
    33→    ///
    34→    /// # Arguments
    35→    ///
    36→    /// * `header` - The parent block to make the env out of.
    37→    /// * `base_fee_per_gas` - Base fee per gas for the next block.
    38→    /// * `chain_spec` - The chain hardfork description, must implement [`EthereumHardforks`].
    39→    /// * `chain_id` - The chain identifier.
    40→    /// * `blob_params` - Optional parameters that sets limits on gas and count for blobs.
    41→    pub fn for_eth_next_block(
    42→        header: impl BlockHeader,
    43→        attributes: NextEvmEnvAttributes,
    44→        base_fee_per_gas: u64,
    45→        chain_spec: impl EthereumHardforks,
    46→        chain_id: ChainId,
    47→        blob_params: Option<BlobParams>,
    48→    ) -> Self {
    49→        Self::for_eth_next(
    50→            EvmEnvInput::from_parent_header(header, attributes, base_fee_per_gas),
    51→            chain_spec,
    52→            chain_id,
    53→            blob_params,
    54→        )
    55→    }
    56→
    57→    fn for_eth(
    58→        input: EvmEnvInput,
    59→        chain_spec: impl EthereumHardforks,
    60→        chain_id: ChainId,
    61→        blob_params: Option<BlobParams>,
    62→    ) -> Self {
    63→        let spec =
    64→            crate::spec_by_timestamp_and_block_number(&chain_spec, input.timestamp, input.height);
    65→        let mut cfg_env = CfgEnv::new_with_spec(spec).with_chain_id(chain_id);
    66→
    67→        if let Some(blob_params) = &blob_params {
    68→            cfg_env.set_max_blobs_per_tx(blob_params.max_blobs_per_tx);
    69→        }
    70→
    71→        if chain_spec.is_osaka_active_at_timestamp(input.timestamp) {
    72→            cfg_env.tx_gas_limit_cap = Some(MAX_TX_GAS_LIMIT_OSAKA);
    73→        }
    74→
    75→        // derive the EIP-4844 blob fees from the header's `excess_blob_gas` and the current
    76→        // blob-params
    77→        let blob_excess_gas_and_price =
    78→            input.excess_blob_gas.zip(blob_params).map(|(excess_blob_gas, params)| {
    79→                let blob_gasprice = params.calc_blob_fee(excess_blob_gas);
    80→                BlobExcessGasAndPrice { excess_blob_gas, blob_gasprice }
    81→            });
    82→
    83→        let is_merge_active = chain_spec.is_paris_active_at_block(input.height);
    84→
    85→        let block_env = BlockEnv {
    86→            number: U256::from(input.height),
    87→            beneficiary: input.beneficiary,
    88→            timestamp: U256::from(input.timestamp),
    89→            difficulty: if is_merge_active { U256::ZERO } else { input.difficulty },
    90→            prevrandao: if is_merge_active { input.mix_hash } else { None },
    91→            gas_limit: input.gas_limit,
    92→            basefee: input.base_fee_per_gas,
    93→            blob_excess_gas_and_price,
    94→        };
    95→
    96→        Self::new(cfg_env, block_env)
    97→    }
    98→
    99→    fn for_eth_next(
   100→        input: EvmEnvInput,
   101→        chain_spec: impl EthereumHardforks,
   102→        chain_id: ChainId,
   103→        blob_params: Option<BlobParams>,
   104→    ) -> Self {
   105→        let spec =
   106→            crate::spec_by_timestamp_and_block_number(&chain_spec, input.timestamp, input.height);
   107→        let mut cfg_env = CfgEnv::new_with_spec(spec).with_chain_id(chain_id);
   108→
   109→        if let Some(blob_params) = &blob_params {
   110→            cfg_env.set_max_blobs_per_tx(blob_params.max_blobs_per_tx);
   111→        }
   112→
   113→        if chain_spec.is_osaka_active_at_timestamp(input.timestamp) {
   114→            cfg_env.tx_gas_limit_cap = Some(MAX_TX_GAS_LIMIT_OSAKA);
   115→        }
   116→
   117→        // if the parent block did not have excess blob gas (i.e. it was pre-cancun), but it is
   118→        // cancun now, we need to set the excess blob gas to the default value(0)
   119→        let blob_excess_gas_and_price = blob_params
   120→            .and_then(|blob_params| {
   121→                Some(blob_params.next_block_excess_blob_gas_osaka(
   122→                    input.excess_blob_gas?,
   123→                    input.blob_gas_used?,
   124→                    input.base_fee_per_gas,
   125→                ))
   126→            })
   127→            .or_else(|| (spec == SpecId::CANCUN).then_some(0))
   128→            .map(|excess_blob_gas| {
   129→                let blob_gasprice =
   130→                    blob_params.unwrap_or_else(BlobParams::cancun).calc_blob_fee(excess_blob_gas);
   131→                BlobExcessGasAndPrice { excess_blob_gas, blob_gasprice }
   132→            });
   133→
   134→        let block_env = BlockEnv {
   135→            number: U256::from(input.height),
   136→            beneficiary: input.beneficiary,
   137→            timestamp: U256::from(input.timestamp),
   138→            difficulty: U256::ZERO,
   139→            prevrandao: input.mix_hash,
   140→            gas_limit: input.gas_limit,
   141→            basefee: input.base_fee_per_gas,
   142→            blob_excess_gas_and_price,
   143→        };
   144→
   145→        Self::new(cfg_env, block_env)
   146→    }
   147→}
   148→
   149→pub(crate) struct EvmEnvInput {
   150→    pub(crate) timestamp: BlockTimestamp,
   151→    pub(crate) height: BlockNumber,
   152→    pub(crate) beneficiary: Address,
   153→    pub(crate) mix_hash: Option<B256>,
   154→    pub(crate) difficulty: U256,
   155→    pub(crate) gas_limit: u64,
   156→    pub(crate) excess_blob_gas: Option<u64>,
   157→    pub(crate) base_fee_per_gas: u64,
   158→    pub(crate) blob_gas_used: Option<u64>,
   159→}
   160→
   161→impl EvmEnvInput {
   162→    pub(crate) fn from_block_header(header: impl BlockHeader) -> Self {
   163→        Self {
   164→            timestamp: header.timestamp(),
   165→            height: header.number(),
   166→            beneficiary: header.beneficiary(),
   167→            mix_hash: header.mix_hash(),
   168→            difficulty: header.difficulty(),
   169→            gas_limit: header.gas_limit(),
   170→            excess_blob_gas: header.excess_blob_gas(),
   171→            base_fee_per_gas: header.base_fee_per_gas().unwrap_or_default(),
   172→            blob_gas_used: None,
   173→        }
   174→    }
   175→
   176→    pub(crate) fn from_parent_header(
   177→        header: impl BlockHeader,
   178→        attributes: NextEvmEnvAttributes,
   179→        base_fee_per_gas: u64,
   180→    ) -> Self {
   181→        Self {
   182→            timestamp: attributes.timestamp,
   183→            height: header.number() + 1,
   184→            beneficiary: attributes.suggested_fee_recipient,
   185→            mix_hash: Some(attributes.prev_randao),
   186→            difficulty: header.difficulty(),
   187→            gas_limit: attributes.gas_limit,
   188→            excess_blob_gas: header.excess_blob_gas(),
   189→            base_fee_per_gas,
   190→            blob_gas_used: header.blob_gas_used(),
   191→        }
   192→    }
   193→}
   194→
   195→/// Represents additional attributes required to configure the next block.
   196→///
   197→/// This struct contains all the information needed to build a new block that cannot be
   198→/// derived from the parent block header alone. These attributes are typically provided
   199→/// by the consensus layer (CL) through the Engine API during payload building.
   200→#[derive(Debug, Clone, PartialEq, Eq)]
   201→pub struct NextEvmEnvAttributes {
